/** Renders the facilitator OpenAPI document as a Markdown reference page. */
interface Op {
  summary?: string;
  security?: unknown[];
  parameters?: {
    name: string;
    in: string;
    required?: boolean;
    schema?: { type?: string; default?: unknown };
  }[];
  requestBody?: unknown;
  responses?: Record<string, { description?: string }>;
}

export function renderApi(doc: {
  info: { description: string };
  paths: Record<string, Record<string, Op>>;
}): string {
  const lines = [
    '<!-- Generated by packages/docs-gen from apps/facilitator/src/http/openapi.ts. Do not edit. -->',
    '',
    '# Facilitator HTTP API',
    '',
    doc.info.description,
    '',
    'Machine-readable: [`openapi.json`](/openapi.json) (also served by the facilitator at `GET /openapi.json`).',
    'The seller watcher connects over a WebSocket at `/watcher` (signed login; see the payment channels guide).',
    '',
  ];
  for (const [path, ops] of Object.entries(doc.paths)) {
    for (const [method, op] of Object.entries(ops)) {
      lines.push(`## \`${method.toUpperCase()} ${path}\``, '', op.summary ?? '', '');
      if (op.security?.length) {
        lines.push(
          'Auth: `Authorization: Bearer <key>` when `FACILITATOR_API_KEYS` is set; rate-limited.',
          '',
        );
      }
      if (op.parameters?.length) {
        lines.push('| Query parameter | Type | Required | Default |', '| --- | --- | --- | --- |');
        for (const p of op.parameters) {
          lines.push(
            `| \`${p.name}\` | ${p.schema?.type ?? ''} | ${p.required ? 'yes' : 'no'} | ${p.schema?.default === undefined ? '' : `\`${String(p.schema.default)}\``} |`,
          );
        }
        lines.push('');
      }
      if (op.requestBody)
        lines.push('Body: `{ x402Version, paymentPayload, paymentRequirements }` (x402).', '');
      lines.push('| Status | Meaning |', '| --- | --- |');
      for (const [code, r] of Object.entries(op.responses ?? {}))
        lines.push(`| ${code} | ${r.description ?? ''} |`);
      lines.push('');
    }
  }
  return lines.join('\n');
}
